import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import axios from "axios";

// Fetch all jobs from MongoDB
export const fetchJobs = createAsyncThunk("jobs/fetchJobs", async () => {
  const res = await axios.get("http://localhost:3001/jobs");
  return res.data; // return list of jobs
});

// Add new job to MongoDB
export const addJob = createAsyncThunk("jobs/addJob", async (jobData) => {
  const res = await axios.post("http://localhost:3001/addJob", jobData);
  return res.data.job; // return the created job
});

// Redux slice for job management
const jobSlice = createSlice({
  name: "jobs",
  initialState: { jobs: [], isLoading: false, isError: false },
  reducers: {},

  // Handle API states
  extraReducers: (builder) => {
    builder
      // When fetching jobs
      .addCase(fetchJobs.pending, (state) => {
        state.isLoading = true;
      })
      .addCase(fetchJobs.fulfilled, (state, action) => {
        state.isLoading = false;
        state.jobs = action.payload;
      })
      .addCase(fetchJobs.rejected, (state) => {
        state.isLoading = false;
        state.isError = true;
      })

      // When adding new job
      .addCase(addJob.pending, (state) => {
        state.isLoading = true;
      })
      .addCase(addJob.fulfilled, (state, action) => {
        state.isLoading = false;
        state.jobs.push(action.payload);
      })
      .addCase(addJob.rejected, (state) => {
        state.isLoading = false;
        state.isError = true;
      });
  },
});

export default jobSlice.reducer;
